use DigiForge\Database\Tables;
use DigiForge\Orders\Validator;
use WP_Error;
/** Immutable reviewed image policies bind registered rows and public connector metadata only. */
final class ImageGenerationPolicyRepository
{
 public const ENGINES=['ORIGINAL_ARTWORK','PET_PORTRAIT','WATERCOLOR','LINE_ART','VINTAGE_PORTRAIT','AI_TRANSFORM'];
 public function review(array $input):array|WP_Error {
  $gate=ImageGenerationAccess::authorize();if($gate instanceof WP_Error)return $gate;$policy=$this->normalize($input);if($policy instanceof WP_Error)return $policy;
  $index='digiforge_image_policy_index_'.hash('sha256',$policy['policy_key'].'|'.$policy['version']);
  return ImageGenerationEvidenceStore::locked($index,function()use($policy,$index):array|WP_Error {
   $existing=ImageGenerationEvidenceStore::load($index);if($existing instanceof WP_Error)return $existing;if($existing!==null){$old=$this->verified((string)($existing['hash']??''));return is_array($old)&&ImageGenerationEvidenceStore::digest($old['policy'])===ImageGenerationEvidenceStore::digest($policy)?$old:ImageGenerationEvidenceStore::error('policy_version_conflict');}
   $pins=$this->pins($policy);if($pins instanceof WP_Error)return $pins;$record=ImageGenerationEvidenceStore::seal(['policy'=>$policy,'reviewed_by'=>get_current_user_id(),'reviewed_at'=>gmdate('Y-m-d H:i:s')]+$pins,'hash');$saved=ImageGenerationEvidenceStore::put('digiforge_image_policy_'.$record['hash'],$record);if($saved instanceof WP_Error)return $saved;$audit=ImageGenerationEvidenceStore::audit('policy_review',$record['hash'],$record['hash']);if($audit instanceof WP_Error)return $audit;$saved=ImageGenerationEvidenceStore::put($index,['hash'=>$record['hash']]);return $saved instanceof WP_Error?$saved:$this->public($record);
  });
 }
 public function read(string $hash):array|WP_Error {$gate=ImageGenerationAccess::authorize();return $gate instanceof WP_Error?$gate:$this->verified($hash);}
