 public function recent():array|WP_Error {$gate=ImageGenerationAccess::authorize();if($gate instanceof WP_Error)return $gate;global $wpdb;$wpdb->last_error='';$rows=$wpdb->get_col($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name LIKE %s ORDER BY option_id DESC LIMIT 30',$wpdb->esc_like('digiforge_image_policy_index_').'%'));if($wpdb->last_error!==''||!is_array($rows))return ImageGenerationEvidenceStore::error('store_unavailable');$items=[];foreach($rows as $raw){$index=json_decode((string)$raw,true);$record=$this->verified((string)($index['hash']??''));if($record instanceof WP_Error)return $record;$items[]=$record;}return $items;}
 private function normalize(array $p):array|WP_Error {
  $keys=['policy_key','version','binding','integration_id','size','quality','maximum_task_charge','currency','timeout_seconds','max_output_bytes','engines','prompt_version','terms_source_sha256','enabled'];if(array_diff(array_keys($p),$keys)!==[]||array_diff(array_diff($keys,['enabled']),array_keys($p))!==[])return ImageGenerationEvidenceStore::error('policy_fields');$p['enabled']=$p['enabled']??false;
  foreach(['policy_key','version','prompt_version']as $key)if(!ImageGenerationEvidenceStore::token($p[$key]))return ImageGenerationEvidenceStore::error('policy_token');
  try{StageTaskBinding::validate($p['binding']);}catch(\Throwable){return ImageGenerationEvidenceStore::error('policy_binding');}if(count($p['binding'])!==2||array_diff(array_keys($p['binding']),['task_id','provider_models'])!==[]||count($p['binding']['provider_models'])>30)return ImageGenerationEvidenceStore::error('policy_binding');
  if(is_array($p['engines']))foreach($p['engines']as $engine)if(!is_string($engine))return ImageGenerationEvidenceStore::error('policy_engine');
  $charge=MonetaryReservationRepository::micros($p['maximum_task_charge']);if($charge instanceof WP_Error||$charge<1||!is_string($p['maximum_task_charge']))return ImageGenerationEvidenceStore::error('policy_charge');$p['maximum_task_charge']=intdiv($charge,1000000).'.'.str_pad((string)($charge%1000000),6,'0',STR_PAD_LEFT);
  if(!is_int($p['integration_id'])||$p['integration_id']<1||!in_array($p['size'],ImageGenerationWireContract::SUPPORTED_SIZES,true)||!in_array($p['quality'],['low','medium','high'],true)||!is_string($p['currency'])||preg_match('/^[A-Z]{3}$/D',$p['currency'])!==1||!is_bool($p['enabled'])||!is_int($p['timeout_seconds'])||$p['timeout_seconds']<1||$p['timeout_seconds']>120||!is_int($p['max_output_bytes'])||$p['max_output_bytes']<1||$p['max_output_bytes']>2097152||!ImageGenerationEvidenceStore::hash($p['terms_source_sha256'])||!is_array($p['engines'])||!array_is_list($p['engines'])||$p['engines']===[]||count(array_unique($p['engines'],SORT_REGULAR))!==count($p['engines'])||array_diff($p['engines'],self::ENGINES)!==[])return ImageGenerationEvidenceStore::error('policy_contract');
  sort($p['engines']);ksort($p['binding']['provider_models']);return json_decode(Validator::canonicalJson($p),true);
 }
 private function pins(array $policy):array|WP_Error {
  $route=StageTaskBinding::load($policy['binding']);if($route instanceof WP_Error)return $route;$repo=new Repository();$task=$repo->find(Tables::ai_tasks(),$policy['binding']['task_id']);$model=$repo->find(Tables::ai_models(),$route['model_id']);if(!is_array($task)||!is_array($model)||!in_array('image_generation',$task['required_capabilities']??[],true)||($model['model_class']??null)!=='image'||!in_array('image_generation',$model['capabilities']??[],true)||$route['provider_model']!=='gpt-image-1')return ImageGenerationEvidenceStore::error('image_route_required');
  $repo=new \DigiForge\Integrations\Repository();$integration=$repo->find($policy['integration_id']);if($integration instanceof WP_Error)return $integration;if(!is_array($integration)||$integration['provider']!=='ai'||$integration['environment']!=='production'||$integration['status']!=='CONFIGURED')return ImageGenerationEvidenceStore::error('integration_required');$secrets=$repo->secretMetadata($policy['integration_id']);if($secrets instanceof WP_Error)return $secrets;if(count($secrets)!==1||($secrets[0]['secret_name']??null)!=='api_key'||!is_string($secrets[0]['fingerprint']??null)||preg_match('/^[a-f0-9]{16}$/D',$secrets[0]['fingerprint'])!==1)return ImageGenerationEvidenceStore::error('credential_metadata_required');
  global $wpdb;$wpdb->last_error='';$taskRow=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::ai_tasks().' WHERE id=%d',$policy['binding']['task_id']),ARRAY_A);if($wpdb->last_error!==''||!is_array($taskRow))return ImageGenerationEvidenceStore::error('task_snapshot');$wpdb->last_error='';$modelRow=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::ai_models().' WHERE id=%d',$route['model_id']),ARRAY_A);if($wpdb->last_error!==''||!is_array($modelRow))return ImageGenerationEvidenceStore::error('model_snapshot');
  return ['route'=>$route,'task_sha256'=>ImageGenerationEvidenceStore::digest($taskRow),'model_sha256'=>ImageGenerationEvidenceStore::digest($modelRow),'integration_sha256'=>ImageGenerationEvidenceStore::digest($integration),'credential_sha256'=>ImageGenerationEvidenceStore::digest($secrets)];
 }
 private function verified(string $hash):array|WP_Error {if(!ImageGenerationEvidenceStore::hash($hash))return ImageGenerationEvidenceStore::error('policy_hash');$record=ImageGenerationEvidenceStore::load('digiforge_image_policy_'.$hash);if(!is_array($record)||!ImageGenerationEvidenceStore::valid($record,'hash')||($record['hash']??null)!==$hash||!ImageGenerationEvidenceStore::audited('policy_review',$hash,$hash,(int)($record['reviewed_by']??0)))return ImageGenerationEvidenceStore::error('policy_integrity');$policy=$this->normalize($record['policy']??[]);if($policy instanceof WP_Error||$policy!==$record['policy'])return ImageGenerationEvidenceStore::error('policy_integrity');$index=ImageGenerationEvidenceStore::load('digiforge_image_policy_index_'.hash('sha256',$policy['policy_key'].'|'.$policy['version']));if(!is_array($index)||($index['hash']??null)!==$hash)return ImageGenerationEvidenceStore::error('policy_index');return $this->public($record);}
 private function public(array $record):array {unset($record['_seal']);return json_decode(Validator::canonicalJson($record),true);}
}
